using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketsController : ControllerBase
{
    private readonly TicketClassifierService _classifierService;

    public TicketsController(TicketClassifierService classifierService)
    {
        _classifierService = classifierService;
    }

    [HttpPost("classify")]
    public IActionResult Classify([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Description))
            return BadRequest(new { error = "Subject and Description are required." });

        if (request.Priority < 1 || request.Priority > 3)
            return BadRequest(new { error = "Priority must be between 1 and 3." });

        var prediction = _classifierService.Predict(request);

        return Ok(new
        {
            predictedCategory = prediction.Category,
            confidence = prediction.Score.Max()
        });
    }

    [HttpGet("metrics")]
    public IActionResult GetMetrics()
    {
        var metrics = _classifierService.GetMetrics();
        return Ok(metrics);
    }
}

